import{_ as e,c as o,o as r,a0 as a}from"./chunks/framework.C1J0Vcxi.js";const _=JSON.parse('{"title":"第二十八周：K3 实体板上手与 RT24 UART/加载链硬件验证","description":"","frontmatter":{"title":"第二十八周：K3 实体板上手与 RT24 UART/加载链硬件验证","date":"2026-06-23"},"headers":[],"relativePath":"周报-Oveln/2026-06-23-周报二十八.md","filePath":"周报-Oveln/2026-06-23-周报二十八.md"}'),l={name:"周报-Oveln/2026-06-23-周报二十八.md"};function s(d,t,n,i,c,h){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="第二十八周工作总结" tabindex="-1">第二十八周工作总结 <a class="header-anchor" href="#第二十八周工作总结" aria-label="Permalink to &quot;第二十八周工作总结&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>上周完成了 K3 RT24 启动机制的全链路调研，结论是&quot;rt-async 可直接复用官方 <code>esos.itb</code> 打包链，无需自实现唤醒逻辑&quot;。本周从调研转入<strong>实体板硬件实操</strong>，目标是把加载链在真实 K3 板子上跑通，并先点亮 RT24 的 UART 通路。</p><p>进展与遇到的问题：</p><ol><li><strong>串口线踩坑</strong>：官方盒装串口线经环回测试确认损坏，换自制线后成功刷机。</li><li><strong>RT24 UART 输出已通、输入异常</strong>：RT24 (rcpu) 的 UART <strong>输出正常</strong>，但<strong>输入存在字符错误</strong>，初步怀疑串口转换芯片驱动能力不足，仍在排查。</li><li><strong>加载链最小化验证</strong>：用极简的 <code>simplehello.elf</code> 替换 <code>esos</code> 在 rcpu1 上的固件，验证&quot;自定义程序能否被 SPL 唤醒并在 RT24 上执行&quot;，仍在调试。</li></ol><h2 id="_1-串口线问题-环回测试定位硬件故障" tabindex="-1">1. 串口线问题（环回测试定位硬件故障） <a class="header-anchor" href="#_1-串口线问题-环回测试定位硬件故障" aria-label="Permalink to &quot;1. 串口线问题（环回测试定位硬件故障）&quot;">​</a></h2><p>用官方盒装串口线连板子，刷机与交互时好时坏、数据乱码。将串口线 <strong>TX/RX 短接做环回自收发测试</strong>，结果发送字节与接收字节对不上，确认线缆（或其内部 USB 转串口芯片/接线）存在物理故障。</p><ul><li>官方盒装串口线确认为坏件，弃用；改用自制线后<strong>刷机成功</strong>，后续 UART 调试均基于自制线。</li></ul><h2 id="_2-rt24-uart-输出已通-输入字符错误-排查中" tabindex="-1">2. RT24 UART 输出已通 / 输入字符错误（排查中） <a class="header-anchor" href="#_2-rt24-uart-输出已通-输入字符错误-排查中" aria-label="Permalink to &quot;2. RT24 UART 输出已通 / 输入字符错误（排查中）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><strong>RT24 → 主机（输出）</strong></td><td>✅ 正常</td><td>RT24 经 R_UART0 发送的字符主机能正确接收</td></tr><tr><td><strong>主机 → RT24（输入）</strong></td><td>⚠️ 异常</td><td>主机下发到 RT24 的字符存在错码/丢字符</td></tr></tbody></table><p>输出方向完全正常、输入方向出错，<strong>初步怀疑串口转换芯片驱动能力不足</strong>：输出由板载 UART 驱动发送、转换芯片接收（链路负担轻）；输入由转换芯片驱动发送、板载 UART 接收，若芯片驱动能力弱（电平摆率/驱动电流不足），可能导致板载端采样出错。</p><p>待排查：换不同型号 USB 转串口线对比；用示波器/逻辑分析仪抓输入波形；核对波特率分频与采样点是否与 R_UART（PXA-UART）预期一致。</p><h2 id="_3-加载链最小化验证-simplehello-elf-替换-rcpu1-固件" tabindex="-1">3. 加载链最小化验证：simplehello.elf 替换 rcpu1 固件 <a class="header-anchor" href="#_3-加载链最小化验证-simplehello-elf-替换-rcpu1-固件" aria-label="Permalink to &quot;3. 加载链最小化验证：simplehello.elf 替换 rcpu1 固件&quot;">​</a></h2><p>理论上一条&quot;把任意 ELF 塞进 <code>rcpu1-fw</code> 节点即可在 RT24 上跑&quot;的结论上周已成立，但<strong>未在真实硬件上验证过</strong>。本周编写极简 <code>simplehello.elf</code>（仅最小启动初始化 + UART 循环输出，不依赖任何 RTOS/中断/复杂驱动），替换 <code>esos.itb</code> 中 rcpu1 固件节点重打包，观察 RT24 核 1 是否被唤醒并执行输出。</p><p><strong>为何先不上 rt-async</strong>：rt-async 启动涉及 <code>__Start</code>、trap、PLIC、定时器、内存布局等多重环节，若直接替换后无响应，无法区分&quot;加载链没通&quot;还是&quot;rt-async 自身初始化失败&quot;。<code>simplehello.elf</code> 把变量降到最少——<strong>只要它在 RT24 上输出，就证明加载链是通的</strong>。仍在调试中，卡点下周补充。</p><h2 id="_4-本周在-k3-迁移中的位置" tabindex="-1">4. 本周在 K3 迁移中的位置 <a class="header-anchor" href="#_4-本周在-k3-迁移中的位置" aria-label="Permalink to &quot;4. 本周在 K3 迁移中的位置&quot;">​</a></h2><p>对应 <a href="./../项目计划/项目计划-20260528.html">项目计划-20260528</a> K3 适配第一阶段，与上周&quot;下周计划&quot;对齐：</p><table tabindex="0"><thead><tr><th>上周计划项</th><th>本周状态</th></tr></thead><tbody><tr><td>在 R_UART0 看到 rt-async 启动日志</td><td>🟡 UART 输出已通（simplehello 验证），输入待修；rt-async 本体未上板</td></tr><tr><td>用 <code>esos_rt24_sign.its</code> 打包自定义 ELF</td><td>🟡 打包链跑通，simplehello 替换调试中</td></tr><tr><td>实现 PXA-UART <code>Chip::put_str</code> + CCU 时钟使能</td><td>⏳ 待加载链验证通过后推进</td></tr></tbody></table><p>加载链（SPL → rproc → RT24）是整个迁移的地基，本周用 simplehello 把地基单独夯实——地基不通，后续改址、PXA-UART 驱动、PLIC 适配都是空中楼阁。</p><h2 id="_5-下周计划" tabindex="-1">5. 下周计划 <a class="header-anchor" href="#_5-下周计划" aria-label="Permalink to &quot;5. 下周计划&quot;">​</a></h2><ol><li><strong>定位 UART 输入字符错误根因</strong>：换线对比 + 波形抓取，确认是否串口芯片驱动能力问题。</li><li><strong>跑通 simplehello 在 RT24 上的加载与执行</strong>，打通最小加载链。</li><li>加载链验证通过后，启动 <code>modules/chip-k3-rt24/</code>，实现 PXA-UART <code>Chip::put_str</code> + CCU 时钟使能。</li><li>目标：在 R_UART0 看到 <strong>rt-async 自身</strong>的启动日志（而非 simplehello）。</li></ol>',21)])])}const T=e(l,[["render",s]]);export{_ as __pageData,T as default};
